import { useCallback, useEffect, useRef, useState } from "react";
import { Chess } from "chess.js";
import { Chessboard } from "react-chessboard";
import { io } from "socket.io-client";

const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || "http://localhost:3001";

// ─── Helpers ─────────────────────────────────────────────────────────────────
function fmt(ms) {
  const s = Math.max(0, Math.ceil((ms || 0) / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function kingSquare(chess, color) {
  for (const row of chess.board())
    for (const sq of row)
      if (sq?.type === "k" && sq.color === color) return sq.square;
  return null;
}

const PIECE_UNICODE = { wq:"♛",wr:"♜",wb:"♝",wn:"♞",bq:"♕",br:"♖",bb:"♗",bn:"♘" };

// ─── Sub-components ───────────────────────────────────────────────────────────

function Clock({ ms, active, low }) {
  return (
    <div style={{
      fontFamily: "'Courier New', monospace",
      fontSize: 22,
      fontVariantNumeric: "tabular-nums",
      letterSpacing: 2,
      padding: "6px 14px",
      borderRadius: 6,
      background: active ? "rgba(200,169,110,0.12)" : "rgba(0,0,0,0.2)",
      border: `1px solid ${active ? "#c8a96e" : "#2e2820"}`,
      color: low ? "#e05252" : active ? "#c8a96e" : "#6b5f4b",
      transition: "all 0.3s",
      minWidth: 72,
      textAlign: "center",
    }}>
      {fmt(ms)}
    </div>
  );
}

function PlayerRow({ name, isMe, active, ms, low }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "10px 14px", borderRadius: 7,
      background: active ? "#1e1a16" : "#131210",
      border: `1px solid ${active ? "#3a3228" : "#1c1812"}`,
      transition: "all 0.2s",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        {active && <span style={{
          width: 7, height: 7, borderRadius: "50%",
          background: "#c8a96e", boxShadow: "0 0 8px #c8a96e",
          animation: "pulse 1.2s ease-in-out infinite",
        }} />}
        <span style={{
          fontStyle: "italic", fontSize: 14,
          color: active ? "#e8e0d0" : "#6b5f4b",
        }}>
          {name}{isMe && <span style={{ color: "#4a4035", marginLeft: 6 }}>(you)</span>}
        </span>
      </div>
      <Clock ms={ms} active={active} low={low} />
    </div>
  );
}

function MoveHistory({ history }) {
  const ref = useRef(null);
  useEffect(() => { if (ref.current) ref.current.scrollTop = ref.current.scrollHeight; }, [history]);

  const pairs = [];
  for (let i = 0; i < history.length; i += 2)
    pairs.push({ n: Math.floor(i / 2) + 1, w: history[i], b: history[i + 1] });

  return (
    <div style={{
      background: "#0f0e0c", border: "1px solid #1e1a16", borderRadius: 7,
      padding: "8px 6px", overflowY: "auto", flex: 1,
    }} ref={ref}>
      <div style={{ fontSize: 10, letterSpacing: 2, color: "#4a4035", textTransform: "uppercase", padding: "0 6px 6px" }}>
        Moves
      </div>
      {pairs.length === 0
        ? <div style={{ color: "#3a3228", fontSize: 12, padding: "6px 8px", fontStyle: "italic" }}>No moves yet</div>
        : pairs.map(p => (
          <div key={p.n} style={{
            display: "grid", gridTemplateColumns: "28px 1fr 1fr",
            gap: 4, padding: "3px 6px", borderRadius: 4, alignItems: "center",
          }}>
            <span style={{ fontSize: 11, color: "#3a3228" }}>{p.n}.</span>
            <span style={{ fontSize: 13, color: "#b8a98a", padding: "1px 5px", borderRadius: 3,
              background: "rgba(200,169,110,0.06)", cursor: "default" }}>{p.w}</span>
            {p.b && <span style={{ fontSize: 13, color: "#8a7a62", padding: "1px 5px", borderRadius: 3,
              cursor: "default" }}>{p.b}</span>}
          </div>
        ))}
    </div>
  );
}

function Chat({ messages, onSend, myName }) {
  const [input, setInput] = useState("");
  const ref = useRef(null);
  useEffect(() => { if (ref.current) ref.current.scrollTop = ref.current.scrollHeight; }, [messages]);

  const send = () => {
    const txt = input.trim();
    if (!txt) return;
    onSend(txt);
    setInput("");
  };

  return (
    <div style={{
      display: "flex", flexDirection: "column", gap: 0,
      background: "#0f0e0c", border: "1px solid #1e1a16", borderRadius: 7,
      overflow: "hidden", height: 180,
    }}>
      <div style={{ fontSize: 10, letterSpacing: 2, color: "#4a4035", textTransform: "uppercase",
        padding: "7px 10px 5px", borderBottom: "1px solid #1a1612" }}>
        Chat
      </div>
      <div style={{ flex: 1, overflowY: "auto", padding: "6px 10px", display: "flex", flexDirection: "column", gap: 5 }} ref={ref}>
        {messages.length === 0
          ? <div style={{ color: "#2e2820", fontSize: 12, fontStyle: "italic" }}>No messages yet…</div>
          : messages.map((m, i) => (
            <div key={i} style={{
              display: "flex", gap: 6, alignItems: "baseline",
              flexDirection: m.from === myName ? "row-reverse" : "row",
            }}>
              <span style={{ fontSize: 11, color: "#4a4035", whiteSpace: "nowrap" }}>{m.from}</span>
              <span style={{
                fontSize: 13, color: m.from === myName ? "#c8a96e" : "#a09080",
                background: m.from === myName ? "rgba(200,169,110,0.08)" : "rgba(255,255,255,0.04)",
                padding: "3px 8px", borderRadius: 10, maxWidth: "70%", wordBreak: "break-word",
              }}>{m.text}</span>
            </div>
          ))}
      </div>
      <div style={{ display: "flex", borderTop: "1px solid #1a1612" }}>
        <input
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => e.key === "Enter" && send()}
          placeholder="Send a message…"
          maxLength={120}
          style={{
            flex: 1, background: "transparent", border: "none", outline: "none",
            color: "#b8a98a", fontSize: 13, padding: "8px 10px",
            fontFamily: "Georgia, serif",
          }}
        />
        <button onClick={send} style={{
          background: "transparent", border: "none", cursor: "pointer",
          color: "#4a4035", fontSize: 16, padding: "0 12px",
          transition: "color 0.15s",
        }} onMouseEnter={e => e.target.style.color = "#c8a96e"}
          onMouseLeave={e => e.target.style.color = "#4a4035"}>
          ➤
        </button>
      </div>
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const socketRef = useRef(null);
  const chessRef = useRef(new Chess());

  const [phase, setPhase] = useState("lobby");       // lobby | waiting | game | ended
  const [selectedTC, setSelectedTC] = useState(5);
  const [roomId, setRoomId] = useState(null);
  const [myColor, setMyColor] = useState("w");
  const [myName, setMyName] = useState("");
  const [opponentName, setOpponentName] = useState("");
  const [fen, setFen] = useState("start");
  const [turn, setTurn] = useState("w");
  const [clocks, setClocks] = useState({ w: 300000, b: 300000 });
  const [history, setHistory] = useState([]);
  const [lastMove, setLastMove] = useState(null);
  const [gameOver, setGameOver] = useState(null);
  const [status, setStatus] = useState("");
  const [drawOffered, setDrawOffered] = useState(false);

  // Click-to-move
  const [selectedSq, setSelectedSq] = useState(null);
  const [optionSquares, setOptionSquares] = useState({});

  // Chat
  const [chatMessages, setChatMessages] = useState([]);

  // ─── Socket ────────────────────────────────────────────────────────────────
  useEffect(() => {
    const socket = io(SOCKET_URL, { transports: ["websocket"] });
    socketRef.current = socket;

    socket.on("assignedName", ({ name }) => setMyName(name));
    socket.on("waitingForOpponent", () => setPhase("waiting"));
    socket.on("queueCancelled", () => setPhase("lobby"));

    socket.on("gameStart", ({ roomId, color, opponentName, myName: mn, fen, timeControl, clocks, turn }) => {
      chessRef.current = new Chess();
      setRoomId(roomId);
      setMyColor(color);
      setOpponentName(opponentName);
      if (mn) setMyName(mn);
      setFen(fen);
      setTurn(turn);
      setClocks(clocks);
      setHistory([]);
      setLastMove(null);
      setGameOver(null);
      setDrawOffered(false);
      setSelectedSq(null);
      setOptionSquares({});
      setChatMessages([]);
      setStatus(`${timeControl}m · ${color === "w" ? "You play White" : "You play Black"}`);
      setPhase("game");
    });

    socket.on("moveUpdate", ({ fen, turn, move, clocks }) => {
      chessRef.current.load(fen);
      setFen(fen);
      setTurn(turn);
      setClocks(clocks);
      setHistory(chessRef.current.history());
      if (move) setLastMove({ from: move.from, to: move.to });
      setSelectedSq(null);
      setOptionSquares({});
    });

    socket.on("clockUpdate", ({ clocks }) => setClocks({ ...clocks }));

    socket.on("moveRejected", ({ reason }) => {
      setStatus(`⚠ ${reason}`);
      setSelectedSq(null);
      setOptionSquares({});
    });

    socket.on("gameOver", ({ reason, winner, winnerName, clocks }) => {
      if (clocks) setClocks(clocks);
      setGameOver({ reason, winner, winnerName });
      setPhase("ended");
    });

    socket.on("chatMessage", ({ from, text }) => {
      setChatMessages(prev => [...prev, { from, text }]);
    });

    socket.on("drawOffered", () => setDrawOffered(true));
    socket.on("drawDeclined", () => setStatus("Draw declined."));

    return () => socket.disconnect();
  }, []);

  // ─── Move hints (click-to-move) ───────────────────────────────────────────
  const getMoveOptions = useCallback((square) => {
    const moves = chessRef.current.moves({ square, verbose: true });
    if (!moves.length) return {};
    const styles = {};
    moves.forEach(m => {
      const isCapture = chessRef.current.get(m.to);
      styles[m.to] = isCapture
        ? {
            background: "radial-gradient(circle, rgba(220,50,50,0) 55%, rgba(220,50,50,0.55) 55%)",
            borderRadius: "50%",
          }
        : {
            background: "radial-gradient(circle, rgba(200,169,110,0.75) 25%, transparent 26%)",
            borderRadius: "50%",
          };
    });
    return styles;
  }, []);

  const onSquareClick = useCallback((square) => {
    if (phase !== "game" || turn !== myColor) return;
    const chess = chessRef.current;

    // If a square is already selected
    if (selectedSq) {
      // Try to make the move
      const moves = chess.moves({ square: selectedSq, verbose: true });
      const target = moves.find(m => m.to === square);

      if (target) {
        const promotion =
          target.piece === "p" &&
          ((myColor === "w" && square[1] === "8") || (myColor === "b" && square[1] === "1"))
            ? "q" : undefined;

        socketRef.current?.emit("makeMove", {
          roomId,
          move: { from: selectedSq, to: square, promotion },
        });
        setSelectedSq(null);
        setOptionSquares({});
        return;
      }
    }

    // Select new square if it has a piece of our color
    const piece = chess.get(square);
    if (piece && piece.color === myColor) {
      setSelectedSq(square);
      setOptionSquares(getMoveOptions(square));
    } else {
      setSelectedSq(null);
      setOptionSquares({});
    }
  }, [phase, turn, myColor, selectedSq, roomId, getMoveOptions]);

  const onPieceDrop = useCallback((from, to, piece) => {
    if (turn !== myColor) return false;
    const promotion =
      piece[1] === "P" &&
      ((myColor === "w" && to[1] === "8") || (myColor === "b" && to[1] === "1"))
        ? "q" : undefined;
    socketRef.current?.emit("makeMove", { roomId, move: { from, to, promotion } });
    return true;
  }, [turn, myColor, roomId]);

  // ─── Chat ─────────────────────────────────────────────────────────────────
  const sendChat = useCallback((text) => {
    socketRef.current?.emit("chatMessage", { roomId, text });
    setChatMessages(prev => [...prev, { from: myName, text }]);
  }, [roomId, myName]);

  // ─── Actions ──────────────────────────────────────────────────────────────
  const findGame = () => {
    socketRef.current?.emit("findGame", { timeControl: selectedTC });
    setPhase("waiting");
  };
  const cancelQueue = () => socketRef.current?.emit("cancelQueue");
  const resign = () => { if (window.confirm("Resign?")) socketRef.current?.emit("resign", { roomId }); };
  const offerDraw = () => { socketRef.current?.emit("offerDraw", { roomId }); setStatus("Draw offered…"); };
  const acceptDraw = () => { socketRef.current?.emit("acceptDraw", { roomId }); setDrawOffered(false); };
  const declineDraw = () => { socketRef.current?.emit("declineDraw", { roomId }); setDrawOffered(false); };
  const playAgain = () => { setPhase("lobby"); setGameOver(null); setFen("start"); chessRef.current = new Chess(); };

  // ─── Board decoration ─────────────────────────────────────────────────────
  const chess = chessRef.current;
  const inCheck = phase === "game" && chess.inCheck();
  const kingPos = inCheck ? kingSquare(chess, turn) : null;

  const customSquareStyles = { ...optionSquares };

  if (lastMove) {
    customSquareStyles[lastMove.from] = {
      ...customSquareStyles[lastMove.from],
      backgroundColor: "rgba(200,169,110,0.28)",
    };
    customSquareStyles[lastMove.to] = {
      ...customSquareStyles[lastMove.to],
      backgroundColor: "rgba(200,169,110,0.45)",
    };
  }
  if (selectedSq) {
    customSquareStyles[selectedSq] = {
      ...customSquareStyles[selectedSq],
      backgroundColor: "rgba(200,169,110,0.55)",
      boxShadow: "inset 0 0 0 3px rgba(200,169,110,0.8)",
    };
  }
  if (kingPos) {
    customSquareStyles[kingPos] = {
      ...customSquareStyles[kingPos],
      background: "radial-gradient(circle at center, #e0524a 0%, rgba(220,50,50,0.6) 50%, transparent 75%)",
      boxShadow: "inset 0 0 0 2px rgba(220,50,50,0.9)",
    };
  }

  // ─── Derived ──────────────────────────────────────────────────────────────
  const oppColor = myColor === "w" ? "b" : "w";
  const isMyTurn = phase === "game" && turn === myColor;
  const myMs = clocks[myColor] ?? 0;
  const oppMs = clocks[oppColor] ?? 0;

  // ─── Render ───────────────────────────────────────────────────────────────
  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IM+Fell+English:ital@0;1&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { background: #0d0d0f; }
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }
        @keyframes checkGlow { 0%,100% { box-shadow: 0 0 0 2px rgba(220,50,50,0.5); }
          50% { box-shadow: 0 0 16px 4px rgba(220,50,50,0.8); } }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: #2e2820; border-radius: 2px; }
      `}</style>

      <div style={{
        minHeight: "100vh", background: "#0d0d0f", color: "#e8e0d0",
        fontFamily: "'IM Fell English', Georgia, serif",
        display: "flex", flexDirection: "column", alignItems: "center",
        padding: "20px 16px",
      }}>

        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 28,
          fontSize: 12, letterSpacing: 4, color: "#4a4035", textTransform: "uppercase" }}>
          <div style={{ width: 60, height: 1, background: "linear-gradient(90deg, transparent, #3a3228)" }} />
          ♟ Chess Arena
          <div style={{ width: 60, height: 1, background: "linear-gradient(90deg, #3a3228, transparent)" }} />
        </div>

        {/* ── LOBBY ────────────────────────────────────────────────────────── */}
        {phase === "lobby" && (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 24, maxWidth: 360, width: "100%" }}>
            <h1 style={{ fontSize: 44, fontWeight: 400, color: "#e8e0d0", textAlign: "center", lineHeight: 1.1 }}>Find a Game</h1>
            <p style={{ fontSize: 12, color: "#4a4035", letterSpacing: 3, textTransform: "uppercase" }}>Real-time · Server validated</p>
            {myName && (
              <div style={{ background: "#1a1714", border: "1px solid #2e2820", borderRadius: 6,
                padding: "10px 20px", fontSize: 14, color: "#b8a98a", fontStyle: "italic" }}>
                Playing as: {myName}
              </div>
            )}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, width: "100%" }}>
              {[1, 3, 5, 10].map(tc => (
                <button key={tc} onClick={() => setSelectedTC(tc)} style={{
                  background: selectedTC === tc ? "#c8a96e" : "#1a1714",
                  border: `1px solid ${selectedTC === tc ? "#c8a96e" : "#2e2820"}`,
                  color: selectedTC === tc ? "#0d0d0f" : "#b8a98a",
                  borderRadius: 6, padding: 14, fontSize: 18, fontFamily: "inherit",
                  cursor: "pointer", transition: "all 0.15s",
                  display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
                }}>
                  {tc}
                  <span style={{ fontSize: 10, letterSpacing: 2, textTransform: "uppercase" }}>min</span>
                </button>
              ))}
            </div>
            <button onClick={findGame} style={{
              width: "100%", padding: 16,
              background: "linear-gradient(135deg, #c8a96e 0%, #a07840 100%)",
              border: "none", borderRadius: 6, color: "#0d0d0f",
              fontSize: 13, letterSpacing: 3, textTransform: "uppercase",
              fontFamily: "inherit", cursor: "pointer",
            }}>
              Find Opponent
            </button>
          </div>
        )}

        {/* ── WAITING ──────────────────────────────────────────────────────── */}
        {phase === "waiting" && (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20, color: "#b8a98a" }}>
            <div style={{ width: 40, height: 40, border: "2px solid #2e2820",
              borderTop: "2px solid #c8a96e", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
            <p>Seeking opponent for {selectedTC}min…</p>
            <button onClick={cancelQueue} style={{
              background: "transparent", border: "1px solid #2e2820", color: "#6b5f4b",
              padding: "10px 24px", borderRadius: 6, cursor: "pointer",
              fontFamily: "inherit", fontSize: 13, letterSpacing: 2,
            }}>Cancel</button>
          </div>
        )}

        {/* ── GAME ─────────────────────────────────────────────────────────── */}
        {(phase === "game" || phase === "ended") && (
          <div style={{
            display: "flex", gap: 16, alignItems: "flex-start",
            width: "100%", maxWidth: 900,
          }}>

            {/* Board column */}
            <div style={{ display: "flex", flexDirection: "column", gap: 8, flex: "0 0 auto", width: "min(520px, 100%)" }}>

              <PlayerRow
                name={opponentName} isMe={false}
                active={turn === oppColor && phase === "game"}
                ms={oppMs} low={oppMs < 10000}
              />

              <div style={{
                borderRadius: 4, overflow: "hidden",
                boxShadow: inCheck && turn === myColor
                  ? "0 0 0 3px rgba(220,50,50,0.7), 0 20px 60px rgba(0,0,0,0.8)"
                  : "0 20px 60px rgba(0,0,0,0.8), 0 0 0 1px #2e2820",
                animation: inCheck && turn === myColor ? "checkGlow 1.5s ease-in-out infinite" : "none",
                transition: "box-shadow 0.3s",
              }}>
                <Chessboard
                  position={fen}
                  onPieceDrop={onPieceDrop}
                  onSquareClick={onSquareClick}
                  boardOrientation={myColor === "w" ? "white" : "black"}
                  arePiecesDraggable={isMyTurn}
                  customSquareStyles={customSquareStyles}
                  customDarkSquareStyle={{ backgroundColor: "#5a4a3a" }}
                  customLightSquareStyle={{ backgroundColor: "#d4c5a9" }}
                  customBoardStyle={{ borderRadius: 0 }}
                  animationDuration={120}
                />
              </div>

              <PlayerRow
                name={myName} isMe={true}
                active={isMyTurn}
                ms={myMs} low={myMs < 10000}
              />

              <div style={{ fontSize: 11, letterSpacing: 2, color: "#4a4035",
                textTransform: "uppercase", minHeight: 18, textAlign: "center" }}>
                {inCheck && turn === myColor
                  ? "⚠ check"
                  : isMyTurn ? "your move" : status}
              </div>

              {drawOffered && (
                <div style={{
                  display: "flex", alignItems: "center", gap: 10,
                  background: "#1e1a16", border: "1px solid #3a3228",
                  borderRadius: 7, padding: "10px 14px", fontSize: 13, color: "#b8a98a",
                }}>
                  <span style={{ flex: 1 }}>Opponent offers a draw</span>
                  <button onClick={acceptDraw} style={ghostBtn}>Accept</button>
                  <button onClick={declineDraw} style={{ ...ghostBtn, color: "#e05252", borderColor: "#6b2020" }}>Decline</button>
                </div>
              )}

              {phase === "game" && (
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={offerDraw} style={ghostBtn}>Offer Draw</button>
                  <button onClick={resign} style={{ ...ghostBtn, color: "#e05252", borderColor: "#6b2020" }}>Resign</button>
                </div>
              )}
            </div>

            {/* Side panel */}
            <div style={{
              flex: 1, display: "flex", flexDirection: "column", gap: 10,
              minWidth: 0, alignSelf: "stretch",
            }}>
              <MoveHistory history={history} />
              <Chat messages={chatMessages} onSend={sendChat} myName={myName} />
            </div>
          </div>
        )}

        {/* ── GAME OVER OVERLAY ──────────────────────────────────────────── */}
        {phase === "ended" && gameOver && (
          <div style={{
            position: "fixed", inset: 0, background: "rgba(0,0,0,0.75)",
            display: "flex", alignItems: "center", justifyContent: "center",
            zIndex: 100, backdropFilter: "blur(4px)",
          }}>
            <div style={{
              background: "#1a1714", border: "1px solid #2e2820", borderRadius: 12,
              padding: "44px 40px", textAlign: "center", maxWidth: 320, width: "90%",
              display: "flex", flexDirection: "column", gap: 14,
            }}>
              {gameOver.winner === null ? (
                <>
                  <div style={{ fontSize: 52 }}>½</div>
                  <h2 style={{ fontSize: 30, fontWeight: 400, color: "#e8e0d0" }}>Draw</h2>
                  <p style={{ fontSize: 12, color: "#6b5f4b", letterSpacing: 2, textTransform: "uppercase" }}>{gameOver.reason}</p>
                </>
              ) : gameOver.winner === myColor ? (
                <>
                  <div style={{ fontSize: 52 }}>♛</div>
                  <h2 style={{ fontSize: 30, fontWeight: 400, color: "#c8a96e" }}>Victory</h2>
                  <p style={{ fontSize: 12, color: "#6b5f4b", letterSpacing: 2, textTransform: "uppercase" }}>{gameOver.reason}</p>
                </>
              ) : (
                <>
                  <div style={{ fontSize: 52, opacity: 0.5 }}>♟</div>
                  <h2 style={{ fontSize: 30, fontWeight: 400, color: "#6b5f4b" }}>Defeat</h2>
                  <p style={{ fontSize: 12, color: "#4a4035", letterSpacing: 2, textTransform: "uppercase" }}>{gameOver.reason}</p>
                  {gameOver.winnerName && <p style={{ color: "#b8a98a", fontSize: 14 }}>{gameOver.winnerName} wins</p>}
                </>
              )}
              <button onClick={playAgain} style={{
                padding: 14,
                background: "linear-gradient(135deg, #c8a96e 0%, #a07840 100%)",
                border: "none", borderRadius: 6, color: "#0d0d0f",
                fontSize: 12, letterSpacing: 3, textTransform: "uppercase",
                fontFamily: "inherit", cursor: "pointer", marginTop: 6,
              }}>Play Again</button>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

const ghostBtn = {
  padding: "8px 16px", border: "1px solid #2e2820", borderRadius: 5,
  background: "transparent", color: "#6b5f4b", fontSize: 11,
  letterSpacing: 2, textTransform: "uppercase", fontFamily: "inherit",
  cursor: "pointer", transition: "all 0.15s",
};
